#!/usr/bin/env python3
# Generated by Claude Opus 5 (Anthropic)
"""session_views — candidate views of a whole session, rendered at panel size.

Each view is a self-contained figure (dot + svg + pdf + png); the generated
index.html shows them side by side so four of them can be picked for the
results panel.

  v1 hierarchy   CN -> EX -> N -> E -> F containment, radial, coloured by type
  v2 nodes       node layer (L2): data topics only, coloured by namespace
  v3 executors   executor/process layer (L1)
  v4 census      what the model holds: vertices per layer, edges per nature
  v5 gpu_dag     typed DAG of the dominant signature of the busiest GPU callback
  v6 conditional conditional graph of the same callback
  v7 wcc         largest weakly connected component of the data graph

v5-v7 are copied from the galleries built by dag_signatures.py /
dag_conditional.py / wcc_dag_viz.py when those exist.

Usage: python3 -m postprocess.session_views <session> [--scope __main__]
"""
from __future__ import annotations
import argparse, collections, glob, html, json, os, shutil, subprocess, sys
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
import psycopg2, psycopg2.extras

DSN = os.environ.get('FISH_PG_DSN', 'host=localhost port=5432 dbname=fish user=fish password=fish')
GALLERY = os.path.join('paper', 'dag_gallery')
OUTROOT = os.path.join('paper', 'figures', 'views')
FONT = 'Helvetica'
TYPE_FILL = {'CN': '#37474F', 'EX': '#1976D2', 'N': '#2E7D32', 'E': '#F5C518', 'F': '#C62828'}
NAT_COLOR = {'msg': '#1f77b4', 'join': '#d62728', 'state': '#9467bd', 'dep': '#7f7f7f',
             'polled': '#ff7f0e', 'gxf_internal': '#8c564b', 'external': '#17becf'}
# topics that carry no application data: they connect everything to everything
INFRA = ('/rosout', '/parameter_events', '/diagnostics', '/clock', '/tf_static',
         '/robot_description', '/statistics')
# NITROS type negotiation: every component announces its supported types to the
# container — protocol traffic, not the pipeline's data
INFRA_SUFFIX = ('/_supported_types',)
TOOLING = ('_ros2cli', 'ros2cli', '_ros2_cli')
PALETTE = ['#4E79A7', '#F28E2B', '#59A14F', '#E15759', '#B07AA1', '#76B7B2',
           '#EDC948', '#FF9DA7', '#9C755F', '#BAB0AC']


def render(src, base, engine='dot', pdf=True):
    open(base + '.dot', 'w').write(src)
    ok = True
    for fmt in (['svg', 'pdf', 'png'] if pdf else ['svg', 'png']):
        try:
            subprocess.check_call([engine, f'-T{fmt}'] + (['-Gdpi=150'] if fmt == 'png' else [])
                                  + [base + '.dot', '-o', f'{base}.{fmt}'],
                                  stderr=subprocess.DEVNULL, timeout=1200)
        except Exception as e:
            print(f'   {engine} -T{fmt} failed: {e}'); ok = False
    return ok


def ns_of(full_name, depth=2):
    p = (full_name or '').strip('/').split('/')
    return '/' + '/'.join(p[:depth]) if len(p) > 1 else '/'


def is_tooling(label):
    l = str(label or '')
    return l.startswith(TOOLING)


def is_infra(topic):
    t = topic or ''
    return (any(t == i or t.startswith(i + '/') for i in INFRA)
            or t.endswith(INFRA_SUFFIX))



def containment(cur, sid, scope):
    """F -> E -> N -> EX maps, so callback-level edges (the only ones that carry
    a topic) can be lifted to any layer with the topic filters applied first."""
    up = {}
    for lvl in ('L2_L3', 'L1_L2', 'L0_L1'):
        cur.execute("""SELECT source, target FROM graph_edges WHERE session_id=%s AND scope=%s
                       AND rel='contains' AND level=%s""", (sid, scope, lvl))
        up[lvl] = {r['target']: r['source'] for r in cur.fetchall()}
    f2e, e2n, n2ex = up['L2_L3'], up['L1_L2'], up['L0_L1']
    f2n = {f: e2n[e] for f, e in f2e.items() if e in e2n}
    f2ex = {f: n2ex[n] for f, n in f2n.items() if n in n2ex}
    return f2n, f2ex


def lifted_edges(cur, sid, scope, f2x, keep, data_only=True, drop_self=True):
    """Callback-layer comm edges lifted to the layer f2x maps into."""
    cur.execute("""SELECT source, target, attrs FROM graph_edges
                   WHERE session_id=%s AND scope=%s AND rel='comm' AND level='L3'""", (sid, scope))
    agg = collections.defaultdict(lambda: [0, collections.Counter(), set()])
    for r in cur.fetchall():
        a = r['attrs'] or {}
        if data_only and is_infra(a.get('topic')):
            continue
        u, v = f2x.get(r['source']), f2x.get(r['target'])
        if u is None or v is None or u not in keep or v not in keep:
            continue
        if drop_self and u == v:
            continue
        e = agg[(u, v)]
        e[0] += int(a.get('flow_n') or 0)
        e[1][a.get('nature') or 'msg'] += 1
        if a.get('topic'):
            e[2].add(a['topic'])
    return agg

# ---------------------------------------------------------------- v1 hierarchy
def v1_hierarchy(cur, sid, scope, base):
    cur.execute("""SELECT node_id, type, label FROM graph_nodes
                   WHERE session_id=%s AND scope=%s""", (sid, scope))
    nodes = {r['node_id']: r for r in cur.fetchall()}
    cur.execute("""SELECT source, target FROM graph_edges
                   WHERE session_id=%s AND scope=%s AND rel='contains'""", (sid, scope))
    edges = [(r['source'], r['target']) for r in cur.fetchall()]
    per = collections.Counter(nodes[n]['type'] for n in nodes if n in nodes)
    size = {'CN': 0.30, 'EX': 0.16, 'N': 0.10, 'E': 0.05, 'F': 0.05}
    L = ['digraph hierarchy {', '  layout=twopi; ranksep="1.1 equally"; overlap=false;',
         '  bgcolor=white; splines=false;',
         f'  node [shape=circle, style=filled, label="", penwidth=0.3, color="#FFFFFF", fontname="{FONT}"];',
         '  edge [color="#B0BEC5", penwidth=0.35, arrowhead=none];']
    for nid, r in nodes.items():
        t = r['type']
        L.append(f'  "{nid}" [fillcolor="{TYPE_FILL.get(t, "#999999")}", '
                 f'width={size.get(t, 0.05)}, height={size.get(t, 0.05)}, '
                 f'tooltip="{html.escape(str(r["label"]))} [{t}]"];')
    for s, t in edges:
        if s in nodes and t in nodes:
            L.append(f'  "{s}" -> "{t}";')
    L.append('  subgraph cluster_lg { label="containment"; fontname="%s"; fontsize=11; '
             'style=rounded; color="#CCCCCC";' % FONT)
    prev = None
    for t, name in (('CN', 'container'), ('EX', 'executor'), ('N', 'node'),
                    ('E', 'entity'), ('F', 'callback')):
        L.append(f'    lg_{t} [shape=box, style=filled, fillcolor="{TYPE_FILL[t]}", fontcolor=white, '
                 f'label="{name} ({per.get(t, 0)})", width=0.1, height=0.1, fontsize=10, fontname="{FONT}"];')
        if prev:
            L.append(f'    lg_{prev} -> lg_{t} [style=invis];')
        prev = t
    L.append('  }')
    L.append('}')
    return render('\n'.join(L), base, engine='twopi')


# -------------------------------------------------------------------- v2 nodes
def v2_nodes(cur, sid, scope, base, data_only=True):
    cur.execute("""SELECT node_id, label, full_name FROM graph_nodes
                   WHERE session_id=%s AND scope=%s AND type='N'""", (sid, scope))
    N = {r['node_id']: r for r in cur.fetchall()
         if not (data_only and is_tooling(r['label']))}
    f2n, _ = containment(cur, sid, scope)
    agg = lifted_edges(cur, sid, scope, f2n, set(N), data_only)
    used = {n for k in agg for n in k}
    depth = 2                       # /a/b; collapse to /a when that splits too finely
    if len({ns_of(N[n]['full_name'], 2) for n in used}) > 8:
        depth = 1
    nss = sorted({ns_of(N[n]['full_name'], depth) for n in used})
    col = {ns: PALETTE[i % len(PALETTE)] for i, ns in enumerate(nss)}
    small = len(used) <= 40
    L = ['digraph nodes {',
         ('  layout=dot; rankdir=LR; splines=true; bgcolor=white;' if small else
          '  layout=sfdp; overlap=prism; splines=true; bgcolor=white;'),
         ('  graph [nodesep=0.2, ranksep=0.5];' if small else '  graph [K=0.7, repulsiveforce=1.4];'),
         f'  node [shape=box, style="filled,rounded", fontname="{FONT}", fontsize=7,'
         '        margin="0.04,0.02", color="#555555", penwidth=0.4];',
         '  edge [arrowsize=0.4, penwidth=0.5];']
    for n in used:
        ns = ns_of(N[n]['full_name'], depth)
        L.append(f'  "{n}" [label="{html.escape(str(N[n]["label"]))[:26]}", fillcolor="{col[ns]}", '
                 f'tooltip="{html.escape(str(N[n]["full_name"]))}"];')
    for (u, v), (flow, nats, topics) in agg.items():
        nat = nats.most_common(1)[0][0]
        w = 0.4 + min(1.8, (flow ** 0.5) / 40.0)
        tip = html.escape(', '.join(sorted(topics))[:200])
        L.append(f'  "{u}" -> "{v}" [color="{NAT_COLOR.get(nat, "#999999")}", penwidth={w:.2f}, '
                 f'tooltip="{tip}"];')
    if len(nss) > 1:
        L.append('  subgraph cluster_lg { label="namespace"; fontsize=11; fontname="%s"; '
                 'style=rounded; color="#CCCCCC";' % FONT)
    prev = None
    for i, ns in enumerate(nss[:12] if len(nss) > 1 else []):
        L.append(f'    lgn{i} [label="{html.escape(ns)}", fillcolor="{col[ns]}", fontsize=8];')
        if prev is not None:
            L.append(f'    lgn{prev} -> lgn{i} [style=invis];')
        prev = i
    if len(nss) > 1:
        L.append('  }')
    L.append('}')
    print(f'   {len(used)} nodes, {len(agg)} edges, {len(nss)} namespaces (depth {depth})')
    return render('\n'.join(L), base, engine='dot' if small else 'sfdp')


# ---------------------------------------------------------------- v3 executors
def v3_executors(cur, sid, scope, base, data_only=True):
    cur.execute("""SELECT node_id, label FROM graph_nodes
                   WHERE session_id=%s AND scope=%s AND type='EX'""", (sid, scope))
    EX = {r['node_id']: r['label'] for r in cur.fetchall()
          if not (data_only and is_tooling(r['label']))}
    _, f2ex = containment(cur, sid, scope)
    agg = lifted_edges(cur, sid, scope, f2ex, set(EX), data_only)
    used = {n for k in agg for n in k}
    L = ['digraph executors {', '  rankdir=LR; layout=dot; bgcolor=white; splines=true;',
         '  graph [nodesep=0.18, ranksep=0.5];',
         f'  node [shape=box, style="filled,rounded", fillcolor="#E3F2FD", color="#1976D2",'
         f'        fontname="{FONT}", fontsize=8, margin="0.06,0.03"];',
         '  edge [color="#546E7A", arrowsize=0.5, penwidth=0.7];']
    for n in used:
        L.append(f'  "{n}" [label="{html.escape(str(EX[n]))}"];')
    for (u, v), (flow, nats, topics) in agg.items():
        tip = html.escape(', '.join(sorted(topics))[:200])
        w = 0.5 + min(2.5, (flow ** 0.5) / 30.0)
        L.append(f'  "{u}" -> "{v}" [label="{len(topics)}", fontsize=6, fontcolor="#546E7A", '
                 f'penwidth={w:.2f}, tooltip="{tip}"];')
    L.append('}')
    print(f'   {len(used)} executors, {len(agg)} edges')
    return render('\n'.join(L), base)


# ------------------------------------------------------------------- v4 census
def v4_census(cur, sid, scope, base):
    cur.execute("""SELECT type, count(*) n FROM graph_nodes
                   WHERE session_id=%s AND scope=%s GROUP BY type""", (sid, scope))
    per = {r['type']: r['n'] for r in cur.fetchall()}
    cur.execute("""SELECT level, attrs->>'nature' nat, count(*) n FROM graph_edges
                   WHERE session_id=%s AND scope=%s AND rel='comm' GROUP BY 1,2""", (sid, scope))
    nat = collections.defaultdict(collections.Counter)
    for r in cur.fetchall():
        nat[r['level']][r['nat'] or 'msg'] += r['n']
    cur.execute("""SELECT count(*) n, sum(n_invocations) inv FROM gpu_dags
                   WHERE session_id=%s AND scope=%s""", (sid, scope))
    g = cur.fetchone()
    rows = []
    for t, name in (('CN', 'container'), ('EX', 'executor'), ('N', 'node'),
                    ('E', 'entity'), ('F', 'callback')):
        rows.append((TYPE_FILL[t], name, per.get(t, 0)))
    L = ['digraph census {', '  rankdir=LR; bgcolor=white;',
         f'  node [shape=plaintext, fontname="{FONT}"];']
    def table(title, items, colorize):
        cells = ''.join(
            f'<TR><TD ALIGN="LEFT"><FONT COLOR="{c}">&#9632;</FONT> {html.escape(k)}</TD>'
            f'<TD ALIGN="RIGHT"><B>{v}</B></TD></TR>' for c, k, v in items)
        return (f'<<TABLE BORDER="0" CELLBORDER="0" CELLSPACING="2" CELLPADDING="2">'
                f'<TR><TD COLSPAN="2" ALIGN="LEFT"><B>{title}</B></TD></TR>{cells}</TABLE>>')
    L.append(f'  vtx [label={table("vertices", rows, True)}];')
    eitems = []
    LAYER = {'L0': 'executor', 'L1': 'node', 'L2': 'entity', 'L3': 'callback'}
    for lvl in sorted(nat):
        for k, v in nat[lvl].most_common():
            eitems.append((NAT_COLOR.get(k, '#999999'), f'{LAYER.get(lvl, lvl)}  {k}', v))
    L.append(f'  edg [label={table("edges by layer and nature", eitems, True)}];')
    gitems = [('#C62828', 'GPU-submitting callbacks', g['n'] or 0),
              ('#C62828', 'GPU invocations', int(g['inv'] or 0))]
    L.append(f'  gpu [label={table("GPU", gitems, True)}];')
    L.append('  vtx -> edg [style=invis]; edg -> gpu [style=invis];')
    L.append('}')
    return render('\n'.join(L), base)


# --------------------------------------------------------- v5..v7 from galleries
def pick_gpu_callback(cur, sid, scope):
    cur.execute("""SELECT anchor_type, anchor, node, entity, n_invocations, dags FROM gpu_dags
                   WHERE session_id=%s AND scope=%s ORDER BY n_invocations DESC""", (sid, scope))
    for r in cur.fetchall():
        shapes = r['dags'] if isinstance(r['dags'], list) else json.loads(r['dags'])
        drawable = [s for s in shapes if s.get('nodes') and not s.get('truncated')]
        if not drawable:
            continue
        tag = f"{r['anchor_type']}_{str(r['anchor']).replace('0x','').lower()}"
        nick = (f"{r['node']} ← {r['entity']}" if r['entity'] else r['node']) or f"thread {r['anchor']}"
        return tag, nick, r['n_invocations']
    return None, None, 0


def copy_first(pattern, dest):
    hits = sorted(glob.glob(pattern))
    if not hits:
        return None
    for h in hits[:1]:
        for ext in ('.svg', '.dot', '.png', '.pdf'):
            src = os.path.splitext(h)[0] + ext
            if os.path.exists(src):
                shutil.copy(src, dest + ext)
    return dest + '.svg' if os.path.exists(dest + '.svg') else None


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('session'); ap.add_argument('--scope', default='__main__')
    ap.add_argument('-o', '--outdir', default=None)
    ap.add_argument('--keep-infra', action='store_true', help='keep /rosout, /diagnostics, …')
    a = ap.parse_args()
    out = a.outdir or os.path.join(OUTROOT, a.session)
    os.makedirs(out, exist_ok=True)
    conn = psycopg2.connect(DSN, cursor_factory=psycopg2.extras.RealDictCursor); conn.autocommit = True
    cur = conn.cursor()
    data_only = not a.keep_infra
    made = []

    print('v1 hierarchy …'); v1_hierarchy(cur, a.session, a.scope, os.path.join(out, 'v1_hierarchy'))
    made.append(('v1_hierarchy', 'containment hierarchy — container → executors → nodes → entities → callbacks'))
    print('v2 nodes …'); v2_nodes(cur, a.session, a.scope, os.path.join(out, 'v2_nodes'), data_only)
    made.append(('v2_nodes', 'node layer: data topics only, node coloured by namespace, edge by nature'))
    print('v3 executors …'); v3_executors(cur, a.session, a.scope, os.path.join(out, 'v3_executors'), data_only)
    made.append(('v3_executors', 'executor layer: processes and the message flow between them'))
    print('v4 census …'); v4_census(cur, a.session, a.scope, os.path.join(out, 'v4_census'))
    made.append(('v4_census', 'what the extracted model holds: vertices per layer, edges per nature'))

    tag, nick, inv = pick_gpu_callback(cur, a.session, a.scope)
    if tag:
        sigdir = os.path.join(GALLERY, a.session + '_signatures')
        conddir = os.path.join(GALLERY, a.session + '_conditional')
        if copy_first(os.path.join(sigdir, f'{tag}_sig0_*.svg'), os.path.join(out, 'v5_gpu_dag')):
            made.append(('v5_gpu_dag', f'typed DAG, dominant signature of {nick} ({inv} invocations)'))
        if copy_first(os.path.join(conddir, f'{tag}_fig2.svg'), os.path.join(out, 'v6_conditional')):
            made.append(('v6_conditional', f'conditional graph of {nick}'))
    for cand in (os.path.join(GALLERY, a.session, 'wcc', 'wcc_00.svg'),
                 os.path.join(GALLERY, a.session + '_isaac_unet', 'wcc', 'wcc_00.svg')):
        if os.path.exists(cand) and copy_first(cand, os.path.join(out, 'v7_wcc')):
            made.append(('v7_wcc', 'largest weakly connected component of the callback graph'))
            break

    css = ("body{font-family:system-ui,sans-serif;max-width:1700px;margin:1em auto;color:#222;padding:0 1em}"
           "h1{font-size:1.35em}h2{font-size:1em;color:#1a5490;margin:.2em 0}"
           ".g{display:grid;grid-template-columns:1fr 1fr;gap:14px}"
           ".v{border:1px solid #ddd;border-radius:6px;padding:.7em;background:#fafafa}"
           ".v img{width:100%;height:340px;object-fit:contain;background:#fff;border:1px solid #ccc;border-radius:4px}"
           ".meta{color:#666;font-size:.83em;margin:.3em 0}a{color:#1a5490}")
    cards = ''.join(
        f'<div class="v"><h2>{k}</h2><div class="meta">{html.escape(d)}</div>'
        f'<a href="{k}.svg" target="_blank"><img src="{k}.svg" loading="lazy"></a>'
        f'<div class="meta">' + ' · '.join(
            f'<a href="{k}.{e}">{e}</a>' for e in ('svg', 'pdf', 'png', 'dot')
            if os.path.exists(os.path.join(out, f'{k}.{e}'))) + '</div></div>'
        for k, d in made)
    open(os.path.join(out, 'index.html'), 'w').write(
        f'<!DOCTYPE html><html><head><meta charset="utf-8"><title>FISH session views — {a.session}</title>'
        f'<style>{css}</style></head><body><h1>Session views — {a.session}</h1>'
        f'<p class="meta">Candidate quadrants for the results panel; click a thumbnail for the full '
        f'SVG.  Infrastructure topics ({", ".join(INFRA)}) are excluded from the node and executor '
        f'views unless --keep-infra.</p><div class="g">{cards}</div></body></html>')
    print(f'[views] {os.path.join(out, "index.html")}  ({len(made)} views)')


if __name__ == '__main__':
    main()
